-- Turns the duplicate "private insurance" card into a distinct topic: a
-- comparison of the 4 largest private insurers in Poland. The other card
-- ("Частная медицинская страховка") stays as the generic "how to get a
-- private policy" guide and is NOT touched by this file.
--
-- Sources (Sept 2026): official Medicover/LuxMed/Enel-Med/PZU Zdrowie pricing
-- pages and aggregator comparisons (ubezpieczenia-kalkulator.pl, luxmed.pl,
-- enelsklep.pl, zdrowie.pzu.pl). Prices are approximate individual-plan
-- starting points and vary by age — the card tells users to check the exact
-- price in each insurer's own calculator rather than quoting a fixed number.
--
-- Run in Supabase SQL Editor. Only updates the Russian base columns; the
-- _en/_uz/_tr/_tg/_uk translation columns are left untouched and should be
-- re-translated afterwards (they'll keep showing the old "duplicate" text
-- for other languages until then).

update public.document_guides
set
  name = 'Medicover vs Luxmed vs Enel-Med vs PZU: что выбрать',
  description = 'Рынок частной медстраховки в Польше держится на четырёх крупных игроках — Medicover, LuxMed, Enel-Med и PZU Zdrowie. Базовый набор у всех похож: приём терапевта и специалистов, анализы, телемедицина. Разница не в том, что "входит", а в сети клиник рядом с домом и работой, скорости записи и паре собственных фишек каждой компании.' || chr(10) || chr(10) ||
    'Точная цена у всех четырёх зависит от возраста и считается в калькуляторе на сайте страховой — ориентируйтесь на порядок цифр ниже, а не на них как на финальную стоимость.',
  when_to_get = 'Когда уже решили, что нужна частная страховка (см. карточку «NFZ или частная страховка: что выбрать»), и осталось сравнить конкретных поставщиков.',
  working_hours = null,
  online_booking = 'У всех четырёх — личный кабинет/приложение для записи к врачу и телемедицины',
  waiting_time = 'Полис активируется за 1-2 суток после оплаты у всех четырёх компаний',
  instructions = '["Определите бюджет — базовые индивидуальные пакеты у всех четырёх стартуют в районе 90-150 злотых в месяц", "Проверьте карту клиник-партнёров рядом с домом и работой на сайте каждой компании", "Если важна стоматология — сравните отдельно: у LuxMed отдельная сеть стоматологий почти по всей стране", "Если важна скорость приёма — у Enel-Med действует гарантия записи к специалисту в течение 24 часов", "Если хотите визит к любому врачу вне сети с частичным возвратом денег — эта опция (рефандация) есть у PZU Zdrowie", "Если хотите объединить со страхованием жизни в одном договоре — тоже вариант PZU", "Прежде чем подписывать годовой контракт, попробуйте пакет 1-2 месяца и оцените реальную запись к нужным специалистам"]'::jsonb,
  tips = '["Medicover — собственная сеть клиник и удобное приложение с телемедициной, но к самым востребованным специалистам очередь бывает даже в частной сети", "LuxMed — самая широкая сеть по стране, в том числе в небольших городах, и отдельная сильная стоматология, но пакеты без доплат за визит дороже среднего", "Enel-Med — доступные цены от ~110 злотых в месяц и гарантия приёма к специалисту в течение 24 часов, но в маленьких городах сеть слабее", "PZU Zdrowie — от ~89 злотых в месяц, есть возмещение расходов при визите к врачу вне сети и возможность объединить со страхованием жизни, но собственная сеть клиник меньше, чем у остальных трёх", "Цена везде растёт с возрастом — смотрите стоимость именно для своего возраста в калькуляторе, а не общий ориентир из рекламы"]'::jsonb,
  common_mistakes = '["Сравнивать только цену пакета, не проверив список включённых специалистов и наличие доплат за визит", "Не проверить сеть клиник рядом с домом и работой перед покупкой годового пакета", "Путать пакет «без доплат» и «с доплатами» — при частых визитах вариант с доплатами может выйти дороже", "Ориентироваться на цену, которую видели у друга или в рекламе — она считается по возрасту заявителя"]'::jsonb
where name = 'Медицинская страховка (частная)' and category = 'страхование';
